int originalWidth = sourceImage.getWidth();
int originalHeight = sourceImage.getHeight();
int canvasWidth = originalWidth + 100;
int canvasHeight = originalHeight + 100;

net.coobird.thumbnailator.filters.Canvas canvasFilter = new net.coobird.thumbnailator.filters.Canvas(
    canvasWidth, canvasHeight, 
    net.coobird.thumbnailator.geometry.Positions.CENTER, 
    false, 
    java.awt.Color.BLUE
);

java.awt.image.BufferedImage result = canvasFilter.apply(sourceImage);

assert result.getWidth() == canvasWidth : "Expected canvas width " + canvasWidth + ", got " + result.getWidth();
assert result.getHeight() == canvasHeight : "Expected canvas height " + canvasHeight + ", got " + result.getHeight();
assert result.getRGB(0, 0) == java.awt.Color.BLUE.getRGB() : "Expected blue background at (0,0)";

System.out.println("__CHECK__ Canvas " + result.getWidth() + "x" + result.getHeight() + ", bg=" + result.getRGB(0, 0));
